/* Playlo Game SDK v1. Public integration code; no secrets. */
(()=>{'use strict';let port=null,config=null,readyId=crypto.randomUUID(),init=null;const pending=new Map(),listeners=new Map();
 const validOrigin=s=>{try{return new URL(s).origin===s&&s.startsWith('https://')}catch{return false}};
 const ready=fetch('__playlo__/config.json',{cache:'no-store',credentials:'omit'}).then(r=>{if(!r.ok)throw Error('CONFIG_UNAVAILABLE');return r.json()}).then(c=>{if(Object.keys(c).sort().join(',')!=='buildId,parentOrigin,sdkVersion'||!validOrigin(c.parentOrigin)||c.sdkVersion!==1)throw Error('CONFIG_INVALID');config=c;return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{removeEventListener('message',receive);reject(Error('TIMEOUT'))},60000);function receive(e){const m=e.data;if(port||e.source!==parent||e.origin!==config.parentOrigin||!m||m.type!=='INIT'||m.protocolVersion!==1||m.handshakeId!==readyId||Object.keys(m).sort().join(',')!=='handshakeId,payload,protocolVersion,type'||e.ports.length!==1)return;const p=m.payload,keys=['sessionId','locale','capabilities','saveSchemaVersion','readableSaveSchemas','preview'];if(!p||Object.keys(p).sort().join(',')!==keys.sort().join(',')||typeof p.preview!=='boolean'||!Array.isArray(p.capabilities)||!Array.isArray(p.readableSaveSchemas))return;clearTimeout(timeout);removeEventListener('message',receive);init=p;port=e.ports[0];port.onmessage=receivePort;port.start();resolve({...p})}addEventListener('message',receive);parent.postMessage({protocolVersion:1,type:'READY',handshakeId:readyId,payload:{buildId:c.buildId}},c.parentOrigin)})});
 function receivePort(e){const m=e.data;if(!m||m.protocolVersion!==1||typeof m.requestId!=='string'||!m.payload||JSON.stringify(m).length>71680)return;if(m.type==='PAUSE'||m.type==='RESUME'){if(Object.keys(m.payload).length)return;for(const f of listeners.get(m.type)||[])try{f()}catch{}port.postMessage({protocolVersion:1,type:'ACK',requestId:m.requestId,payload:{operation:m.type}});return}const call=pending.get(m.requestId);if(!call||!['ACK','ERROR','SAVE_RESULT'].includes(m.type))return;pending.delete(m.requestId);clearTimeout(call.timer);if(m.type==='ERROR'){const error=Error(String(m.payload.message||'SDK error'));error.code=m.payload.code;call.reject(error)}else call.resolve(m.payload)}
 async function request(type,payload,requestId=crypto.randomUUID()){await ready;if(!port)throw Error('SESSION_ENDED');const m={protocolVersion:1,type,requestId,payload};if(new TextEncoder().encode(JSON.stringify(m)).length>71680)throw Error('INVALID_MESSAGE');if(pending.has(requestId))throw Error('REQUEST_PENDING');return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(requestId);const e=Error('Uitkomst onbekend; laad de actuele voortgang voordat je opnieuw schrijft.');e.code='TIMEOUT';reject(e)},5000);pending.set(requestId,{resolve,reject,timer});port.postMessage(m)})}
 window.Playlo={ready,request,loadSave:(schemaVersion,requestId)=>request('LOAD_SAVE',{schemaVersion},requestId),save:(schemaVersion,expectedRevision,data,requestId)=>request('SAVE',{schemaVersion,expectedRevision,data},requestId),migrate:(sourceSchema,sourceRevision,targetSchema,data,requestId)=>request('SAVE_MIGRATE',{sourceSchema,sourceRevision,targetSchema,expectedTargetRevision:null,data},requestId),score:(runId,score,durationMs,requestId)=>request('SCORE',{runId,score,durationMs},requestId),gameOver:(runId,result,requestId)=>request('GAME_OVER',{runId,result},requestId),on:(type,fn)=>{if(!['PAUSE','RESUME'].includes(type)||typeof fn!=='function')throw Error('INVALID_MESSAGE');const set=listeners.get(type)||new Set();set.add(fn);listeners.set(type,set);return()=>set.delete(fn)}};
})();
